'use strict'

// Generated by vfs_scaffold_auth. A small in-memory counter of failed attempts per key, for the login route.
// One process only: with several replicas each keeps its own count (good enough to slow down password guessing).

function createLimiter({ max, windowMs, maxKeys = 10000 }) {
  const entries = new Map() // key -> { count, resetAt }

  function sweep(now) {
    for (const [key, entry] of entries) if (entry.resetAt <= now) entries.delete(key)
  }

  function current(key, now) {
    const entry = entries.get(key)
    if (entry && entry.resetAt <= now) {
      entries.delete(key)
      return null
    }
    return entry || null
  }

  return {

    /** { allowed, retryAfterSeconds } — not allowed once `max` failures were recorded in the window. */
    check(key, now = Date.now()) {
      const entry = current(key, now)
      if (!entry || entry.count < max) return { allowed: true, retryAfterSeconds: 0 }
      return { allowed: false, retryAfterSeconds: Math.max(1, Math.ceil((entry.resetAt - now) / 1000)) }
    },
    fail(key, now = Date.now()) {
      const entry = current(key, now)
      if (entry) entry.count += 1
      else {
        if (entries.size >= maxKeys) sweep(now)
        if (entries.size >= maxKeys) entries.delete(entries.keys().next().value)
        entries.set(key, { count: 1, resetAt: now + windowMs })
      }
    },
    reset(key) {
      entries.delete(key)
    },
    size: () => entries.size,
  }
}

module.exports = { createLimiter }
